import csv
import io

_FIELDS = ('sku', 'name', 'qty')


def import_text(text, store, dry_run=False):
    # Parse and validate every row before touching the store, so an invalid
    # row anywhere leaves the store unchanged.
    rows = []
    reader = csv.DictReader(io.StringIO(text))
    for row in reader:
        values = [row.get(name) for name in _FIELDS]
        if any(value is None for value in values):
            raise ValueError('row is missing required field(s) %r: %r' % (_FIELDS, row))
        item = {
            'sku': values[0].strip(),
            'name': values[1].strip(),
            'qty': values[2].strip(),
        }
        if not item['sku']:
            raise ValueError('SKU must be nonempty after trimming: %r' % (row,))
        if not item['name']:
            raise ValueError('name must be nonempty after trimming: %r' % (row,))
        if not all(char in '0123456789' for char in item['qty']) or not item['qty']:
            raise ValueError('quantity must be a nonnegative integer: %r' % (row,))
        item['qty'] = int(item['qty'])
        rows.append(item)

    # Compute the result from the current store state (dry run and real import
    # see the same starting state).
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in rows:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
        else:
            result['created' if before is None else 'updated'] += 1
            result['changes'].append({
                'sku': item['sku'],
                'before': before,
                'after': item,
            })

    # Commit only after all rows have parsed and validated.
    if not dry_run:
        for item in rows:
            store.put(item)

    return result

